/**
 * @summary List supported crops and their diseases
 */
export const getListCropsUrl = (params?: ListCropsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/crops?${stringifiedParams}`
    : `/api/crops`;
};

export const listCrops = async (
  params?: ListCropsParams,
  options?: RequestInit,
): Promise<Crop[]> => {
  return customFetch<Crop[]>(getListCropsUrl(params), {
    ...options,
    method: "GET",
  });
};

